from functools import wraps

def retry_exponential(max_retries=8):
    """Retry a function with exponential backoff on network errors."""
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            retry_delay = 1  # seconds
            attempts = 0
            while True:
                try:
                    return func(*args, **kwargs)
                except (urllib.error.URLError, ConnectionError) as exc:
                    attempts += 1
                    if attempts > max_retries:
                        raise exc
                    time.sleep(retry_delay)
                    retry_delay *= 2
        return wrapper
    return decorator

@retry_exponential(max_retries=5)
def get_stock_price(symbol):
    """Simulated flaky API call"""
    if random.random() < 0.7:
        raise urllib.error.HTTPError(url='https://api.example.com/price/'+symbol, code=503, msg='Service Unavailable', hdrs=None, fp=None)
    return 123.45

if __name__ == '__main__':
