export class GitHubClient {
  private baseUrl = 'https://api.github.com';

  private async request<T>(path: string): Promise<T> {
    const response = await fetch(`${this.baseUrl}${path}`, {
      headers: { Accept: 'application/vnd.github.v3+json' }
    });

    if (!response.ok) {
      const error = await response.json().catch(() => ({}));
      throw new Error(`GitHub API error ${response.status}: ${error.message || response.statusText}`);
    }

    return response.json() as Promise<T>;
  }

  async listUserRepos(username: string): Promise<Repo[]> {
    return this.request<Repo[]>(`/users/${username}/repos`);
  }

  async getRepo(owner: string, repo: string): Promise<Repo> {
    return this.request<Repo>(`/repos/${owner}/${repo}`);
  }
}

// Usage example
async function main() {
  const client = new GitHubClient();
  try {
    const repo = await client.getRepo('octocat', 'Hello-World');
    console.log(repo.full_name); // octocat/Hello-World

    const repos = await client.listUserRepos('octocat');
    console.log(`Found ${repos.length} repos`);
  } catch (error) {
    console.error(error);
  }
}

main();
