Here is Python code to parse and evaluate a simple arithmetic expression string using a recursive-descent parser:

```python
import re

class Parser:
    def __init__(self, expression):
        self.tokens = re.findall(r'\d+|[+\-*/()]', expression)
        self.current = 0

    def parse(self):
        return self.expression()

    def expression(self):
        result = self.term()
        while self.current < len(self.tokens) and self.tokens[self.current] in ('+', '-'):
            if self.tokens[self.current] == '+':
                self.current += 1
                result += self.term()
            elif self.tokens[self.current] == '-':
                self.current += 1
                result -= self.term()
        return result

    def term(self):
        result = self.factor()
        while self.current < len(self.tokens) and self.tokens[self.current] in ('*', '/'):
            if self.tokens[self.current] == '*':
                self.current += 1
                result *= self.factor()
            elif self.tokens[self.current] == '/':
                self.current += 1
                result /= self.factor()
        return result

    def factor(self):
        if self.tokens[self.current] == '(':
            self.current += 1
            result = self.expression()
            self.current += 1
            return result
        else:
            result = int(self.tokens[self.current])
            self.current += 1
            return result

# Example usage:
expression = '3 + 5 * 2'
parser = Parser(expression)
print(parser.parse())  # Output: 13
```

