```jsx
import React, { useState, useEffect } from 'react';

function SummaryTable() {
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    const fetchData = async () => {
      try {
        const response = await fetch('/api/analytics/summary');
        const json = await response.json();
        if (json.status === 'ok') {
          setData(json.data);
        } else {
          throw new Error('API returned status: ' + json.status);
        }
      } catch (err) {
        setError(err);
      } finally {
        setLoading(false);
      }
    };
    fetchData();
  }, []);

  if (loading) return <div>Loading...</div>;
  if (error) return <div>Error: {error.message}</div>;

  return (
    <table>
      <thead>
        <tr><th>Total Users</th><th>Active Today</th><th>Revenue Today</th></tr>
      </thead>
      <tbody>
        <tr><td>{data.total_users}</td><td>{data.active_today}</td><td>{data.revenue_today}</td></tr>
      </tbody>
    </table>
  );
}

export default SummaryTable;
```

This replaces the jQuery `$.ajax` call with `fetch`, uses React hooks for state management, and renders the table conditionally based on loading/error/data states.

