import pandas as pd

def main(input_path):
    df = pd.read_parquet(input_path)
    failures = []

    # Check 1: Null percentage per column <= 5%
    null_percent = df.isnull().mean() * 100
    for col in df.columns:
        if null_percent[col] > 5:
            failures.append(f"FAIL: Column '{col}' has {null_percent[col]:.2f}% nulls (>5%)")
        else:
            print(f"PASS: Column '{col}' null% = {null_percent[col]:.2f}")

    # Check 2: order_total > 0
    if 'order_total' in df.columns:
        non_positive = df[df['order_total'] <= 0]
        if not non_positive.empty:
            failures.append(f"FAIL: {len(non_positive)} rows with order_total <= 0")
        else:
            print("PASS: All order_total values are positive")
    else:
        failures.append("FAIL: 'order_total' column not found")

    # Check 3: no duplicate customer_id
    if 'customer_id' in df.columns:
        dup_count = df['customer_id'].duplicated().sum()
        if dup_count > 0:
            failures.append(f"FAIL: {dup_count} duplicate customer_ids")
        else:
            print("PASS: No duplicate customer_ids")
    else:
        failures.append("FAIL: 'customer_id' column not found")

    if failures:
        print("\n".join(failures))
        sys.exit(1)
    else:
        print("ALL CHECKS PASSED")

if __name__ == "__main__":
    if len(sys.argv) != 2:
        print("Usage: python validate_checks.py <input_parquet_path>")
        sys.exit(2)
    main(sys.argv[1])"}

