{"file_path": "file_stats_core.py", "content": "import sys
from collections import Counter

def compute_stats(data):
    text = data.decode('utf-8', errors='replace') if isinstance(data, bytes) else data
    bytes_count = len(data) if isinstance(data, bytes) else len(text.encode('utf-8'))
    lines = text.splitlines()
    line_count = len(lines)
    word_count = len(text.split())
    char_count = len(text)
    return {'bytes': bytes_count, 'lines': line_count, 'words': word_count, 'chars': char_count}

def main(args):
    try:
        if args.file:
            with open(args.file, 'rb') as f:
                data = f.read()
            source = args.file
        else:
            data = sys.stdin.buffer.read()
            source = ''
        stats = compute_stats(data)
        keys = ['bytes', 'lines', 'words', 'chars']
        selected = [k for k in keys if getattr(args, k)]
        if not selected:
            selected = keys
        output = []
        for k in selected:
            output.append(f'{stats[k]} {source}'.strip())  # strip trailing space for stdin
        print('\n'.join(output))
    except FileNotFoundError as e:
        print(f'Error: file not found: {e.filename}', file=sys.stderr)
        sys.exit(1)
    except PermissionError:
        print(f'Error: permission denied for file: {args.file}', file=sys.stderr)
        sys.exit(1)
    except Exception as e:
        print(f'Unexpected error: {e}', file=sys.stderr)
        sys.exit(1)
"}

{"path": "/scripts/validate_transformed_data.py", "content": "import pandas as pd
import uuid
from datetime import datetime

def validate_parquet(file_path):
    df = pd.read_parquet(file_path)

    # Check 1: No null values
    null_cols = df.columns[df.isnull().any()].tolist()
    assert not null_cols, f"Null values found in columns: {null_cols}"

    # Check 2: order_date format
    for i, date_str in enumerate(df['order_date']):
        try:
            datetime.strptime(date_str, '%Y-%m-%d')
        except ValueError:
            raise AssertionError(f"Invalid order_date at row {i}: {date_str}")

    # Check 3: non-negative total_amount and quantity
    assert (df['total_amount'] >= 0).all(), "Negative total_amount found"
    assert (df['quantity'] >= 0).all(), "Negative quantity found"

    # Check 4: customer_id is UUID v4
    for i, cid in enumerate(df['customer_id']):
        try:
            val = uuid.UUID(cid)
            assert val.version == 4, f"customer_id at row {i} is not version 4"
        except ValueError:
            raise AssertionError(f"Invalid customer_id at row {i}: {cid}")

    print("All validation checks passed.")

if __name__ == "__main__":
    import sys
    validate_parquet(sys.argv[1] if len(sys.argv) > 1 else '/data/transformed_sales_data.parquet')
"}

